    private void btnIniciarSimulacionActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btnIniciarSimulacionActionPerformed
      // 1. Obtenemos la opción seleccionada (0 = 2 comps, 1 = 3 comps, 2 = 4 comps)
    int seleccion = eleccionComputador.getSelectedIndex();
    
    // 2. Calculamos el número real de computadoras
    int numComputadores = seleccion + 2; 
    
    // 3. Creamos la ventana principal de la Interfaz, pasándole el número
    Interfaz ventanaPrincipal = new Interfaz(numComputadores);
    
    // 4. La centramos en la pantalla y la mostramos
    ventanaPrincipal.setLocationRelativeTo(null);
    ventanaPrincipal.setVisible(true);
    
    // 5. Cerramos este menú para liberar memoria
    this.dispose();
    }//GEN-LAST:event_btnIniciarSimulacionActionPerformed

    

